#!/usr/bin/env bash
# Copilot-only PreToolUse guard for Archon build-feature-copilot runs (registered by .github/hooks/archon-run-guard.json;
# Claude Code never reads that file). Why: Archon's copilot provider passes a node's denied_tools to the CLI as excluded
# tool NAMES, so Claude-style `Bash(*--no-verify*)` patterns match nothing there. This hook re-states the safety subset.
# Three layers. (1) An optional .archon/copilot/deny.json (a JSON array of Claude-style deny patterns such as
# `Bash(*--no-verify*)` or `Read(./.env)`, generated by the kit from settings.json permissions.deny; RUN_GUARD_DENY
# overrides the path) is enforced in EVERY session. (2) The run-worktree rules below. (3) Inside an Archon workflow node
# (ARCHON_NODE_EXECUTION set: Archon puts it in the environment of every AI node, and the agent's own shell cannot change
# a hook's environment), the node's own denied_tools, read from the workflow of the run itself: the copy Archon
# snapshotted for it (<archon home>/workspaces/<owner>/<repo>/workflow-source/runs/$WORKFLOW_ID/, whose manifest.json
# names the workflow), else the project's .archon/workflows/build-feature-copilot.yaml; RUN_GUARD_WORKFLOW overrides the
# path. Copilot drops the Bash(...) entries of denied_tools (it has no per-command tool filter), so this is where they
# hold. The node is the last segment of the node path (implement.build-step is build-step). A Bash pattern is matched
# against the whole command and against each part of it (split on && || ; | & and newlines), so `cd x && npm test`
# meets Bash(*npm*) and `true; git -C <main> push` meets Bash(git -C <main> *). A node the workflow does not name gets the
# denied_tools of every node of it together. Each list must be one JSON-style flow list (`denied_tools: ["Bash(...)", ...]`,
# it may span lines): a list in another form, a workflow that is missing, or a node path that is not readable denies every
# call inside a node, whatever the session folder. This layer holds whether or not the run has a worktree.
# The run-worktree rules are active ONLY when the session runs inside an Archon run worktree (a path with /.archon/workspaces/ or /.archon/worktrees/,
# or one of RUN_GUARD_MARKERS, colon separated); anywhere else, the owner's own Copilot chat included, it allows everything.
# Inside a run it refuses a shell command that:
#   - holds --no-verify, or is a `git commit` with -n (also in a bundle such as -an);
#   - is a `git push` with a refspec naming a protected branch (main, HEAD:main, :main, refs/heads/main, +main);
#     RUN_GUARD_PROTECTED adds branches (space separated);
#   - changes into the main checkout (`cd <main> &&`, `cd <main>;`) or runs `git -C <main>`; the main checkout is the first
#     entry of `git worktree list --porcelain` run in the session folder (never hard-coded);
#   - names commit-tickets or sync-main;
#   - runs `backlog task` without BACKLOG_CWD= (a script that edits a ticket runs it with BACKLOG_CWD, a node never does).
# Input (stdin JSON): Claude names (tool_name, tool_input.command, cwd) or Copilot's (toolName, toolArgs as object or JSON
# string, cwd or workingDirectory), or Copilot's batched preToolUse (CLI 1.0.114: {cwd, sessionId, toolCalls: [{id, name,
# args}, ...]}): every call of the batch is checked, and the first one refused refuses the batch. Deny: JSON with permissionDecision "deny" on stdout (top level and in hookSpecificOutput)
# and the reason on stderr with exit 2 (Copilot denies on exit 2). Anything unreadable inside a run is a deny; outside a run
# it is an allow. A deny is final: there is no switch to turn the guard off.
set -uo pipefail

markers="${RUN_GUARD_MARKERS:-/.archon/workspaces/:/.archon/worktrees/}"
in_run() { # in_run <path>: 0 when the path lies inside an Archon run worktree
  local p=$1 m rest=$markers
  [ -n "$p" ] || return 1
  while [ -n "$rest" ]; do
    m=${rest%%:*}; [ "$rest" = "$m" ] && rest="" || rest=${rest#*:}
    [ -n "$m" ] && case "$p/" in *"$m"*) return 0 ;; esac
  done
  return 1
}

payload=$(cat)
deny() { # deny <reason>
  local r="BLOCKED by .archon/copilot/hooks/run-guard.sh: $1"
  if command -v node >/dev/null 2>&1; then
    R="$r" node -e 'const r=process.env.R;console.log(JSON.stringify({permissionDecision:"deny",permissionDecisionReason:r,hookSpecificOutput:{hookEventName:"PreToolUse",permissionDecision:"deny",permissionDecisionReason:r}}))'
  fi
  echo "$r" >&2
  exit 2
}

if ! command -v node >/dev/null 2>&1; then
  in_run "${PWD:-}" && deny "node is not on the PATH, so the guard cannot read the tool call (inside an Archon run it refuses rather than waves it through)"
  [ -z "${ARCHON_NODE_EXECUTION:-}" ] || deny "node is not on the PATH, so the guard cannot read the tool call (inside an Archon workflow node it refuses rather than waves it through)"
  exit 0
fi

# shellcheck disable=SC2016  # the node program is single-quoted on purpose
verdict=$(PAYLOAD="$payload" RUN_GUARD_MARKERS="$markers" node -e '
const { execFileSync } = require("child_process");
const markers = (process.env.RUN_GUARD_MARKERS || "").split(":").filter(Boolean);
const inRun = p => !!p && markers.some(m => (p + "/").includes(m));
let o = null;
try { o = JSON.parse(process.env.PAYLOAD || ""); } catch { /* handled below */ }
const dirs = [o && (o.cwd || o.workingDirectory), process.cwd(), process.env.COPILOT_PROJECT_DIR, process.env.CLAUDE_PROJECT_DIR].filter(Boolean);
const run = dirs.some(inRun);
const fs = require("fs"), path = require("path");
// the project root: the hook environment, else the git top level of the session folder, else the folder itself
let root = process.env.CLAUDE_PROJECT_DIR || process.env.COPILOT_PROJECT_DIR || "";
if (!root) { try { root = execFileSync("git", ["-C", dirs[0], "rev-parse", "--show-toplevel"], { encoding: "utf8", stdio: ["ignore", "pipe", "ignore"] }).trim(); } catch { root = dirs[0]; } }
// optional deny list (Claude-style patterns, written by the kit from settings.json permissions.deny): every session
let patterns = [];
const denyFile = process.env.RUN_GUARD_DENY || path.join(root, ".archon", "copilot", "deny.json");
try { const d = JSON.parse(fs.readFileSync(denyFile, "utf8")); if (Array.isArray(d)) patterns = d.filter(x => typeof x === "string"); } catch { /* no list, or not readable: none */ }
// (3) inside an Archon workflow node: the denied_tools of that node, read from the workflow (see the header)
const inNode = !!process.env.ARCHON_NODE_EXECUTION;
let nodeName = "", nodePatterns = [], nodeWhy = "", wfShown = "";
if (inNode) {
  try { const p = JSON.parse(process.env.ARCHON_NODE_EXECUTION).path; if (typeof p === "string") nodeName = p.split(".").pop(); } catch { /* below */ }
  if (!/^[A-Za-z0-9_-]+$/.test(nodeName)) { console.log("DENY\tthe node of this Archon run is not readable (ARCHON_NODE_EXECUTION has no node path), so its denied_tools cannot be checked"); process.exit(0); }
  // the workflow of this run: the copy Archon snapshotted for it (its manifest names the workflow), else the project copy
  // of build-feature-copilot.yaml; RUN_GUARD_WORKFLOW overrides both
  let wf = process.env.RUN_GUARD_WORKFLOW || "", snapErr = "";
  const wid = process.env.WORKFLOW_ID || "";
  if (!wf && /^[A-Za-z0-9_-]+$/.test(wid)) {
    const ws = path.join(process.env.ARCHON_HOME || path.join(require("os").homedir(), ".archon"), "workspaces");
    let snap = "";
    try {
      for (const owner of fs.readdirSync(ws)) {
        let repos = [];
        try { repos = fs.readdirSync(path.join(ws, owner)); } catch { continue; }
        for (const repo of repos) {
          const d = path.join(ws, owner, repo, "workflow-source", "runs", wid);
          if (fs.existsSync(path.join(d, "manifest.json"))) { snap = d; break; }
        }
        if (snap) break;
      }
    } catch { /* no workspaces folder: the project copy */ }
    if (snap) {
      let name = "";
      try { name = JSON.parse(fs.readFileSync(path.join(snap, "manifest.json"), "utf8")).workflow_name; } catch { /* below */ }
      if (typeof name !== "string" || !name) snapErr = "the snapshot manifest of run " + wid + " names no workflow";
      else {
        // project workflows first, as Archon resolves them, then the bundled ones
        const walk = d => { let out = []; let es = []; try { es = fs.readdirSync(d, { withFileTypes: true }); } catch { return out; }
          for (const e of es.sort((a, b) => (a.name < b.name ? -1 : 1))) { const f = path.join(d, e.name);
            if (e.isDirectory()) out = out.concat(walk(f)); else if (/\.ya?ml$/.test(e.name)) out.push(f); }
          return out; };
        const esc = x => x.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
        const nameRe = new RegExp("^name:\\s*[\"\x27]?" + esc(name) + "[\"\x27]?\\s*(#.*)?$", "m");
        for (const f of walk(path.join(snap, "project", ".archon", "workflows")).concat(walk(path.join(snap, "bundled")))) {
          try { if (nameRe.test(fs.readFileSync(f, "utf8"))) { wf = f; break; } } catch { /* next */ }
        }
        if (!wf) snapErr = "workflow " + name + " is not in the snapshot of run " + wid;
      }
    }
  }
  if (snapErr) { console.log("DENY\t" + snapErr + ", so the denied_tools of node " + nodeName + " cannot be checked"); process.exit(0); }
  if (!wf) wf = path.join(root, ".archon", "workflows", "build-feature-copilot.yaml");
  wfShown = path.relative(root, wf).startsWith("..") ? wf : path.relative(root, wf);
  // { nodeId: [patterns] } for every `- id:` of the workflow; a node with no denied_tools has []
  const parseDenied = text => {
    const out = Object.create(null); let id = null;
    const lines = text.split("\n");
    let block = -1; // inside a block scalar (prompt: |) whose key sits at this column
    for (let i = 0; i < lines.length; i++) {
      const l = lines[i];
      const col = l.length - l.trimStart().length;
      if (block >= 0) { if (!l.trim() || col > block) continue; block = -1; }
      if (/^\s*#/.test(l)) continue;
      const bs = /^(\s*(?:-\s+)?)[A-Za-z0-9_-]+\s*:\s*[|>][-+0-9]*\s*(#.*)?$/.exec(l);
      if (bs) { block = bs[1].length; continue; }
      let m = /^\s*-\s+id:\s*["\x27]?([A-Za-z0-9_-]+)["\x27]?\s*(#.*)?$/.exec(l);
      if (m) { id = m[1]; if (!out[id]) out[id] = []; continue; }
      if (!/^\s*denied_tools\s*:/.test(l)) continue;
      m = /^\s*denied_tools\s*:\s*(\[.*)$/.exec(l);
      if (!m) throw new Error("line " + (i + 1) + ": denied_tools is not a flow list [...]");
      if (id === null) throw new Error("line " + (i + 1) + ": denied_tools before any node id");
      let buf = m[1], j = i, end = -1;
      for (;;) {
        let depth = 0, inStr = false;
        for (let k = 0; k < buf.length; k++) {
          const c = buf[k];
          if (inStr) { if (c === "\\") k++; else if (c === "\"") inStr = false; continue; }
          if (c === "\"") inStr = true;
          else if (c === "[") depth++;
          else if (c === "]" && --depth === 0) { end = k; break; }
        }
        if (end >= 0) break;
        if (++j >= lines.length) throw new Error("line " + (i + 1) + ": denied_tools list never closes");
        buf += "\n" + lines[j];
      }
      if (!/^\s*(#.*)?$/.test(buf.slice(end + 1))) throw new Error("line " + (j + 1) + ": text after the denied_tools list");
      const list = JSON.parse(buf.slice(0, end + 1));
      if (!Array.isArray(list) || list.some(x => typeof x !== "string")) throw new Error("line " + (i + 1) + ": denied_tools holds a value that is not a string");
      out[id].push(...list);
      i = j;
    }
    return out;
  };
  let rules = null;
  try { rules = parseDenied(fs.readFileSync(wf, "utf8")); } catch (e) {
    console.log("DENY\tthe denied_tools of the workflow are not readable (" + wfShown + ": " + String(e && e.message || e).split("\n")[0] + "), so the rules of node " + nodeName + " cannot be checked");
    process.exit(0);
  }
  if (Object.prototype.hasOwnProperty.call(rules, nodeName)) { nodePatterns = rules[nodeName]; nodeWhy = "node " + nodeName; }
  else { nodePatterns = [...new Set(Object.values(rules).flat())]; nodeWhy = "node " + nodeName + " (not in the workflow, so the denied_tools of all its nodes)"; }
}
if (!run && !patterns.length && !inNode) { console.log("ALLOW"); process.exit(0); }
if (!o || typeof o !== "object") { console.log(run || inNode ? "DENY\tthe hook input is not readable JSON" : "ALLOW"); process.exit(0); }
// one entry per tool call: a batch (toolCalls) holds several, any other payload one
const calls = Array.isArray(o.toolCalls)
  ? o.toolCalls.map(c => (c && typeof c === "object" ? { tool: String(c.name || ""), args: c.args } : { tool: "", args: undefined }))
  : [{ tool: String(o.tool_name || o.toolName || ""), args: o.tool_input !== undefined ? o.tool_input : o.toolArgs }];
// Copilot tool names to Claude names, through the same map the audit uses (.archon/copilot/tools.json)
let toolMap = { view: "Read", create: "Write", edit: "Edit", str_replace_editor: "Edit", grep: "Grep", glob: "Glob" };
try { toolMap = Object.assign(toolMap, JSON.parse(fs.readFileSync(path.join(root, ".archon", "copilot", "tools.json"), "utf8")).tools || {}); } catch { /* built-in names only */ }
let main = null; // the main checkout, looked up once
const check = (tool, args) => {
  const mapped = toolMap[tool.toLowerCase()];
  const claudeTool = mapped ? (typeof mapped === "string" ? mapped : mapped.as) : (/^(bash|shell|powershell|run_shell_command|run_in_terminal)$/i.test(tool) ? "Bash" : tool);
  if (typeof args === "string") { try { args = JSON.parse(args); } catch { args = { command: args }; } }
  const isShell = claudeTool === "Bash";
  const cmd = args && typeof args === "object" ? (args.command || args.cmd || "") : "";
  const target = args && typeof args === "object" ? String(args.file_path || args.path || "") : "";
  const globRe = g => new RegExp("^" + g.replace(/:\*$/, "*").replace(/[.+?^${}()|[\]\\]/g, "\\$&").replace(/\*/g, ".*") + "$", "s");
  const blocks = (pat, t, val) => { // pat is `Tool` or `Tool(glob)`
    const m = /^([A-Za-z_][\w-]*)(?:\((.*)\))?$/s.exec(pat);
    if (!m || m[1] !== t) return false;
    return m[2] === undefined || m[2] === "" ? true : globRe(m[2].replace(/^\.\//, "")).test(String(val).replace(/^\.\//, ""));
  };
  for (const pat of patterns) {
    if (blocks(pat, claudeTool, isShell ? cmd : target)) { console.log("DENY\tthe project deny list (.archon/copilot/deny.json) holds " + pat); process.exit(0); }
  }
  if (inNode) {
    if (isShell && (typeof cmd !== "string" || !cmd.trim())) { console.log("DENY\tthe shell command is not readable in the hook input"); process.exit(0); }
    // the whole command and each part of it, so a rule meets its command anywhere in a chain
    const vals = isShell ? [cmd].concat(String(cmd).split(/&&|\|\||[;&|\n]/).map(x => x.trim()).filter(Boolean)) : [target];
    for (const pat of nodePatterns) {
      if (vals.some(v => blocks(pat, claudeTool, v))) { console.log("DENY\tthe denied_tools of " + nodeWhy + " in " + wfShown + " hold " + pat); process.exit(0); }
    }
  }
  if (!run || !isShell) return;
  if (typeof cmd !== "string" || !cmd.trim()) { console.log("DENY\tthe shell command is not readable in the hook input"); process.exit(0); }
  const deny = why => { console.log("DENY\t" + why); process.exit(0); };

  // the main checkout: first entry of `git worktree list --porcelain` in the session folder
  if (main === null) {
    main = process.env.RUN_GUARD_MAIN || "";
    for (const d of main ? [] : dirs.filter(inRun)) {
      try {
        const out = execFileSync("git", ["-C", d, "worktree", "list", "--porcelain"], { encoding: "utf8", stdio: ["ignore", "pipe", "ignore"] });
        const m = /^worktree (.+)$/m.exec(out);
        if (m) { main = m[1]; break; }
      } catch { /* try the next folder */ }
    }
  }
  const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const protectedBranches = ["main"].concat((process.env.RUN_GUARD_PROTECTED || "").split(/\s+/).filter(Boolean));

  if (/--no-verify/.test(cmd)) deny("--no-verify skips the commit hooks");
  if (/(^|[^A-Za-z0-9_-])(commit-tickets|sync-main)/.test(cmd)) deny("commit-tickets and sync-main write to the main checkout");
  if (main) {
    const m = esc(main);
    if (new RegExp("(^|[\\s;&|(])cd\\s+[\"\x27]?" + m + "(/[^\\s;&|\"\x27]*)?[\"\x27]?\\s*(&&|;|\\|\\||$)").test(cmd)) deny("a run never works in the main checkout " + main);
    if (new RegExp("git\\s+(-[A-Za-z]\\s+\\S+\\s+)*-C\\s*[\"\x27]?" + m + "([/\\s\"\x27]|$)").test(cmd)) deny("git -C on the main checkout " + main);
  }
  for (const seg of cmd.split(/&&|\|\||[;|\n]/)) {
    const t = seg.trim().split(/\s+/);
    const gi = t.indexOf("git");
    if (gi < 0) continue;
    const rest = t.slice(gi + 1);
    if (rest.includes("commit") && rest.some(x => /^-[A-Za-z]*n[A-Za-z]*$/.test(x))) deny("git commit -n skips the commit hooks");
    if (rest.includes("push")) {
      for (const x of rest.slice(rest.indexOf("push") + 1)) {
        const ref = x.replace(/^["\x27]+|["\x27]+$/g, "").replace(/^\+/, "");
        const dst = ref.includes(":") ? ref.slice(ref.lastIndexOf(":") + 1) : ref;
        if (!ref.startsWith("-") && protectedBranches.some(b => dst === b || dst === "refs/heads/" + b)) deny("git push to " + dst + ": a run pushes its own branch only");
      }
    }
  }
  if (/(^|[^A-Za-z0-9_-])backlog\s+task\b/.test(cmd) && !/BACKLOG_CWD=/.test(cmd)) deny("backlog task without BACKLOG_CWD= (only a ticket script runs it)");
};
for (const c of calls) check(c.tool, c.args);
console.log("ALLOW");
' 2>/dev/null) || verdict=$'DENY\tthe guard failed before it could decide'

case "$verdict" in
  ALLOW) exit 0 ;;
  DENY*) deny "${verdict#DENY$'\t'}" ;;
  *) deny "the guard failed before it could decide" ;;
esac
